// One step at a time: connect → file → processing → result. Existing elements are only
// grouped and shown/hidden; every original control and handler keeps working.
const WIZARD=[['connect','الاتصال'],['file','الملف'],['run','المعالجة'],['result','النتيجة']];
function setupWizard(content,{embedded,connected,hasInput,onEvent}){
 const q=s=>content.querySelector(s),kids=[...content.children];
 content.classList.add('colab-wizard');
 const runRow=q('#colabRun').parentElement,account=q('#colabAccount');
 const tag=(el,step)=>{if(el)el.dataset.ws=step;};
 for(const el of kids){const i=kids.indexOf(el);tag(el,i<=kids.indexOf(account)?'connect':i<kids.indexOf(runRow)?'file':'run');}
 tag(runRow,'file');tag(q('#colabPrivacy'),'connect');tag(q('#colabResult'),'result');
 const keep=account.nextElementSibling;if(keep?.classList.contains('micro'))tag(keep,'run');
 // Session controls move next to the progress they belong to.
 const stopRow=document.createElement('div');stopRow.className='actions';stopRow.dataset.ws='run';stopRow.append(q('#colabStop'));q('#colabError').after(stopRow);
 const resume=q('#colabResume');resume.textContent='متابعة آخر عملية';
 const hint=document.createElement('p');hint.className='inline-error';hint.dataset.ws='file';runRow.before(hint);
 // Result step extras.
 const again=document.createElement('div');again.className='actions';again.dataset.ws='result';
 const another=document.createElement('button');another.className='button secondary full';another.textContent='معالجة ملف آخر';another.onclick=()=>go('file');
 const end=document.createElement('button');end.className='button secondary full';end.textContent='إنهاء جلسة Colab وحذف ملفاتها';end.dataset.stop='1';end.onclick=()=>q('#colabStop').click();
 again.append(another,end);q('#colabResult').after(again);
 const bar=document.createElement('ol');bar.className='wizard-steps';const back=document.createElement('button');back.type='button';back.className='wizard-back';back.textContent='→ رجوع';
 if(!embedded)content.prepend(bar,back);
 let current,visited=new Set();
 function go(step,{scroll=true}={}){current=step;visited.add(step);content.dataset.step=step;
  for(const el of content.children)if(el.dataset.ws)el.classList.toggle('ws-off',el.dataset.ws!==step);
  bar.replaceChildren(...WIZARD.map(([id,label],i)=>{const li=document.createElement('li');li.textContent=(i+1)+'. '+label;li.className=id===step?'active':visited.has(id)?'done':'';if(visited.has(id)&&id!==step){li.tabIndex=0;li.setAttribute('role','button');li.onclick=()=>go(id);}return li;}));
  back.hidden=step==='connect';
  if(scroll)(content.closest('dialog')||content).scrollTo?.({top:0,behavior:'smooth'});
 }
 back.onclick=()=>go(current==='result'?'run':current==='run'?'file':'connect');
 // New messages (errors, review notes, retry) appear in the step that is open.
 new MutationObserver(list=>{for(const m of list)for(const n of m.addedNodes)if(n.nodeType===1&&n.parentElement===content&&!n.dataset.ws&&n!==bar&&n!==back){n.dataset.ws=current;}}).observe(content,{childList:true});
 new MutationObserver(()=>{if(q('#colabResult').children.length&&current!=='result')go('result');}).observe(q('#colabResult'),{childList:true});
 q('#colabRun').addEventListener('click',e=>{hint.textContent='';const missing=!hasInput()?'اختر الملف أولًا':!q('#colabConsent').checked?'فعّل الموافقة تحت':'';if(missing){hint.textContent=missing;e.stopImmediatePropagation();return;}go('run');},true);
 resume.addEventListener('click',()=>go('run'));
 go(connected()?'file':'connect',{scroll:false});
 return{go,get current(){return current;},event(type){if(type==='connected'&&current==='connect')go('file');}};
}
